// Isolated native registration experiment. Generated bytes only; no user browser.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {pathToFileURL}=require('node:url');
const {createHash}=require('node:crypto');
const {chromium}=require('/Users/chris/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
(async()=>{
 const root=__dirname,manifest=JSON.parse(fs.readFileSync(path.join(root,'runtime/input-contract/manifest.json'))),bytes=fs.readFileSync(path.join(root,'runtime/input-contract/grid.png'));
 const rotated=process.argv.includes('--rotated'),suffix=rotated?'-rotated':'';
 const asset=manifest.assets[0];
 assert.equal(manifest.assets.length,1);assert.equal(asset.source.kind,'synthetic');assert.equal(asset.source.provider,'generated-locally');
 assert.equal(asset.mediaType,'image/png');assert.equal(asset.width,64);assert.equal(asset.height,48);
 assert.equal(createHash('sha256').update(bytes).digest('hex'),'b43ac96da9eb85eba8a8244552bf3aad6a9a34f87f67661dd4a1556163b01900','Probe only accepts pinned self-generated PNG');
 if(rotated){asset.pixelToEditor=[0,.25,-5.875,.25,0,-7.875];for(const control of asset.controls){const [x,y]=control.editor;control.editor=[-y,x]}}
 const sourcePaths=['synthetic-underlay-probe.cjs','input-manifest.mjs','input-manifest-checks.mjs','app.js','server.py'];
 const hashes=()=>Object.fromEntries(sourcePaths.map(p=>[p,createHash('sha256').update(fs.readFileSync(path.join(root,p))).digest('hex')]));
 const sourceHashes=hashes();
 const {verifyInputBytes}=await import(pathToFileURL(path.join(root,'input-manifest.mjs')).href);await verifyInputBytes(manifest,new Map([['rgb',bytes]]));
 const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true,args:['--disable-background-networking','--disable-component-update','--host-resolver-rules=MAP * ~NOTFOUND, EXCLUDE 127.0.0.1']});
 try{
  const context=await browser.newContext({viewport:{width:1280,height:900},serviceWorkers:'block'}),blocked=[],errors=[];
  await context.route('**/*',route=>{if(new URL(route.request().url()).origin==='http://127.0.0.1:5191')return route.continue();blocked.push(route.request().url());return route.abort()});
  const page=await context.newPage();page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:5191/');await page.waitForFunction(()=>window.lab?.stage==='ready');
  const snapshot=()=>page.evaluate(()=>({design:window.engine.bridge.makeDesignJsonToSave(),history:JSON.stringify(window.engine.state.data.historyData),storage:JSON.stringify({...localStorage})}));
  const before=await snapshot();
  await page.screenshot({path:path.join(root,`runtime/input-contract/underlay-before${suffix}.png`)});
  const result=await page.evaluate(async({manifest,bytes})=>{
   const e=window.engine,c=e.subsystems.orthoTextureCollection,asset=manifest.assets[0],blob=new Blob([new Uint8Array(bytes)],{type:asset.mediaType}),url=URL.createObjectURL(blob);
   const resource=c.orthoImageResourceFromWorldfile({source:'custom',url,name:'Synthetic calibration grid',width:asset.width,height:asset.height,opacity:1},null),texture=c.createGroundTexture({id:'synthetic-calibration-grid',active:true,disabled:false},resource);
   const origin=c.deps.bridge.getOriginLatLng(),reference=texture.constructor.getDefaultWorldfile(1,1,origin),longitudePerMeter=reference.a/50,latitudePerMeter=-reference.e/50,[a,b,tx,d,f,ty]=asset.pixelToEditor;
   // Manifest uses pixel centers. Native wrapper consumes geographic pixel corners.
   resource.worldfile={a:a*longitudePerMeter,b:b*longitudePerMeter,c:origin.lng+(tx-(a+b)/2)*longitudePerMeter,d:d*latitudePerMeter,e:f*latitudePerMeter,f:origin.lat+(ty-(d+f)/2)*latitudePerMeter};texture.initialize();
   const params=texture.localParameters(),controls=asset.controls.map(control=>{const [col,row]=control.pixel;return{pixel:control.pixel,expected:control.editor,actual:[params.origin.x+params.basis.u.x*(col+.5)*params.dimensions.width/asset.width+params.basis.v.x*(asset.height-row-.5)*params.dimensions.height/asset.height,params.origin.y+params.basis.u.y*(col+.5)*params.dimensions.width/asset.width+params.basis.v.y*(asset.height-row-.5)*params.dimensions.height/asset.height]}});
   await c.loadTexture(texture);c.setGroundTextures([texture]);c.orthoTextureActivityChanged();window.syntheticUnderlay={texture,url};
   return{controls,worldfile:resource.worldfile,local:{origin:[params.origin.x,params.origin.y],center:[texture.params.model.x,texture.params.model.y],width:params.dimensions.width,height:params.dimensions.height,u:[params.basis.u.x,params.basis.u.y],v:[params.basis.v.x,params.basis.v.y]},loaded:texture.isLoaded,groundCount:c.groundTextures.length,activeCount:c.activeGroundTextures.length,errors:window.lab.errors,csp:window.lab.blocked,events:window.lab.notifications};
  },{manifest,bytes:[...bytes]});
  fs.writeFileSync(path.join(root,`runtime/input-contract/underlay-attempt${suffix}.json`),JSON.stringify(result,null,2));
  for(const control of result.controls)assert.ok(Math.hypot(...control.actual.map((v,i)=>v-control.expected[i]))<1e-6,'Native pixel-center registration must match controls');assert.equal(result.loaded,true);assert.equal(result.activeCount,1);
  assert.ok(Math.hypot(...result.local.center)<1e-6,'Native center must be editor origin');
  assert.ok(Math.abs(result.local.width-16)<1e-6&&Math.abs(result.local.height-12)<1e-6,'Native size must be 16 by 12 meters');
  const expected=rotated?{origin:[6,-8],u:[0,1],v:[-1,0]}:{origin:[-8,-6],u:[1,0],v:[0,1]};
  for(const key of Object.keys(expected))assert.ok(Math.hypot(...result.local[key].map((v,i)=>v-expected[key][i]))<1e-6,`Native ${key} must match independent fixture`);
  await page.waitForTimeout(700);await page.screenshot({path:path.join(root,`runtime/input-contract/underlay-2d${suffix}.png`)});
  await page.getByRole('button',{name:'3D',exact:true}).click();await page.waitForTimeout(1200);await page.screenshot({path:path.join(root,`runtime/input-contract/underlay-3d${suffix}.png`)});
  result.cleanup=await page.evaluate(()=>{const c=window.engine.subsystems.orthoTextureCollection;c.setGroundTextures([]);c.orthoTextureActivityChanged();URL.revokeObjectURL(window.syntheticUnderlay.url);delete window.syntheticUnderlay;return{groundCount:c.groundTextures.length,activeCount:c.activeGroundTextures.length}});
  assert.deepEqual(result.cleanup,{groundCount:0,activeCount:0});
  await page.waitForTimeout(500);assert.deepEqual(await snapshot(),before,'Underlay must not change native design, history or browser storage');
  result.designHistoryStorageUnchanged=true;result.rotated=rotated;result.sourceHashes=sourceHashes;assert.deepEqual(hashes(),sourceHashes,'Sources changed during probe');
  result.blocked=blocked;result.pageErrors=errors;result.labErrors=await page.evaluate(()=>window.lab.errors);assert.deepEqual(blocked,[]);assert.deepEqual(errors,[]);assert.deepEqual(result.labErrors,[]);
  fs.writeFileSync(path.join(root,`runtime/input-contract/underlay-probe${suffix}.json`),JSON.stringify(result,null,2));console.log(JSON.stringify(result));
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
